    assert.equal(objectForm.receipt.success, true, objectForm.receipt.error);
    assert.deepEqual(seen, [{ path: "r.txt" }, { path: "r.txt" }]);
  } finally {
    bridge.shutdown();
    fs.rmSync(workspace, { recursive: true, force: true });
